const tabId = 918806481;
const products = await browserjs(tabId, () => {
  // Let's find product cards
  const cards = document.querySelectorAll('[data-selector="prd-card"], [class*="ProductCard"], [class*="product-card"], div[data-itemid], div[data-product-id]');
  const results = [];

  // Also try looking for product titles and prices generically if specific selectors aren't found
  const linkElements = Array.from(document.querySelectorAll('a[href*="/pd/"]'));
  const seen = new Set();

  for (const a of linkElements) {
    const href = a.getAttribute('href');
    if (!href || seen.has(href)) continue;
    // Check if parent has price or title
    const card = a.closest('div[class*="Card"], div[class*="product"], div[class*="item"]') || a.parentElement;
    const text = card ? card.innerText : a.innerText;
    if (text && text.length > 20) {
      seen.add(href);
      results.push({
        href: href.startsWith('http') ? href : 'https://www.lowes.com' + href,
        text: text.slice(0, 300).replace(/\n+/g, ' | ')
      });
    }
  }
  return { cardCount: cards.length, linkCount: results.length, sample: results.slice(0, 15) };
});

