const tabId = 918806481;
const specsTable = await browserjs(tabId, () => {
  // Let's click any "Specifications" button or accordion if closed
  const specBtn = Array.from(document.querySelectorAll('button, a')).find(el => el.innerText.trim().toLowerCase() === 'specifications');
  if (specBtn) specBtn.click();

  const tables = Array.from(document.querySelectorAll('table, ul, dl'));
  const rows = Array.from(document.querySelectorAll('tr, [data-selector="spec-row"], [class*="specRow"]')).map(r => r.innerText.trim());

  return {
    rows: rows.filter(r => r.length > 3).slice(0, 30),
    allTablesText: tables.map(t => t.innerText).filter(t => t.includes('Pieces') || t.includes('Includes') || t.includes('Drive')).slice(0, 5)
  };
});

console.log("Specs Table:", specsTable);

