const tabId = 918806496;
const url = "https://www.lowes.com/search?searchTerm=craftsman+homeowner+tool+set";
await tool.navigate({ tabId, url });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

const results = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/pd/"]'));
  const list = [];
  const seen = new Set();
  for (const a of links) {
    const href = a.getAttribute('href');
    if (!href || seen.has(href)) continue;
    seen.add(href);
    const card = a.closest('div[class*="Card"], div[class*="product"], div[data-itemid]') || a.parentElement;
    list.push({
      title: a.innerText.trim() || card?.innerText?.slice(0, 100),
      href: href.startsWith('http') ? href : 'https://www.lowes.com' + href
    });
  }
  return list.filter(x => x.title && x.title.length > 5).slice(0, 10);
});

console.log(JSON.stringify(results, null, 2));

